def _make_bigbird_mask(seq_len_q, seq_len_k, window_size,
                       num_random_blocks, device):
    # Identical construction to the reference so the mask matches bit-for-bit
    # (same seeded torch.randperm stream, same op order, same device).
    mask = torch.zeros(seq_len_q, seq_len_k, device=device)

    # 1. Local window
    half = window_size // 2
    for i in range(seq_len_q):
        start = i - half
        if start < 0:
            start = 0
        end = i + half + 1
        if end > seq_len_k:
            end = seq_len_k
        mask[i, start:end] = 1

    # 2. Global tokens
    if seq_len_q > 0:
        mask[0, :] = 1
        mask[-1, :] = 1
    if seq_len_k > 0:
        mask[:, 0] = 1
        mask[:, -1] = 1

    # 3. Random attention for each non-global Q row (deterministic stream)
    if num_random_blocks > 0:
        seed = (seq_len_q + seq_len_k * 10007 + window_size * 131
                + num_random_blocks * 17)
        generator = torch.Generator(device=device)
        generator.manual_seed(seed)
        for i in range(1, seq_len_q - 1):
            if seq_len_k <= num_random_blocks:
                mask[i, :] = 1
            else:
                rand_indices = torch.randperm(
                    seq_len_k, device=device,
                    generator=generator)[:num_random_blocks]
                mask[i, rand_indices] = 1

